import { HttpResPaginate, Server_Errors } from '@_core/_client';
import { of, Observable } from 'rxjs';
import { LB_Base } from './builder.list.0.base';

export class LB_Base_API extends LB_Base {
  // Get Paginate API
  protected hitApi = (
    next = this.next,
    error = this.error,
    complete = this.complete,
    beforeHit = this.beforeHit
  ) => {
    beforeHit().subscribe({
      next: () => {
        this._httpUOW.Client.GetsPaginate(this.httpReqPaginate).subscribe({ next, error, complete });
      },
    });
  };
  public beforeHit = (): Observable<LB_Base> => {
    return of(this);
  };
  protected next = (res: HttpResPaginate) => {
    this.httpResPaginate = res;
    this.ds.data = res.records as any;
    this.httpReqPaginate.body.pageNo = res.pageNo;
    this.httpReqPaginate.body.pageSize = res.pageSize;
  };
  protected error = (err: Server_Errors) => {
    /* console.log(err) */
  };
  protected complete = () => {
    /* console.log('Complete Called') */
  };
}
