import { EP } from '../_client';
import { SideBarMenus } from './menu-item.interface';

export const permission = [
  EP.Add,
  EP.Update,
  EP.UpdateStatus,
  EP.Delete,
  EP.Get,
  EP.Gets,
  EP.GetsByIds,
  EP.GetsLookup,
  EP.GetsByIdsLookup,
  EP.GetsPaginate,
  EP.GetsPaginateOptions,
  EP.GetsCSV,
  // EP.None
];
export const defaultChild: SideBarMenus = {
  // icon: 'dashboard',
  // class: '',
  permission: JSON.stringify(permission),
  submenu: [],
};
export const defaultParent: SideBarMenus = {
  ...defaultChild,
  permission: undefined,
  // path: '',
  // icon: 'icon-list',
  // class: 'has-arrow',
};
// PARENT LIST
let id = 1
export function P(title: string, icon: string, emoji:string, link: string, desc: string, submenu: SideBarMenus[]): SideBarMenus {
  return {
    id:id++,
    title,
    desc,
    icon,
    emoji,
    link, // Equal to First Child
    ...defaultParent,
    submenu,
  };
}
// CHILD LIST
export function C(title: string, icon: string, emoji: string, link: string, desc: string = ''): SideBarMenus {
  return {
    id:id++,
    link,
    title,
    desc,
    icon,
    emoji,
    ...defaultChild,
  };
}
