import { FormControl, FormGroup } from '@angular/forms';
import { PageEvent } from '@angular/material/paginator';
import { Sort } from '@angular/material/sort';
import { LB_Base_API } from './builder.list.1.api';

export class LB_Base_SortPaginateFilter extends LB_Base_API {
  public filterRequiredShow = false;
  public filterDefaultShow = false;
  public filterAdvanceShow = false;

  public filterRequired: FormGroup = new FormGroup({});
  public filterDefault: FormGroup = new FormGroup({
    id: new FormControl(null),
    name: new FormControl(null),
    desc: new FormControl(null),
    status: new FormControl(null),
    dateFrom: new FormControl(null),
    dateTo: new FormControl(null),
  }); // Form Filter (For Filter System)
  public filterAdvance: FormGroup = new FormGroup({});

  public init() {
    // this.initDefaultCols();
    this.reset();
    this.refresh();
    return this;
  }
  public reset(): void{
    this.filterDefault.reset();
    this.filterAdvance.reset();

    this.httpReqPaginate.body = {
      pageNo: 1,
      pageSize: 25,
      filter: {
        ...this.filterRequired?.value,
      },
      sort: {
        by: null,
        order: null,
      }
    };

  };
  public fresh(): void{
    this._dialog.closeAll();
    this._notify.clear();

    this.httpReqPaginate.body.filter = {
      ...this.filterRequired?.value,
      ...this.filterDefault.value,
      ...this.filterAdvance?.value
    };
    this.hitApi();
  };
  public refresh(): void{
    this.reset();
    this.fresh();
  };

  public sort(sort: Sort): void{
    console.log({ sort })
    let by = sort.active;
    by = by.charAt(0).toUpperCase() + by.slice(1);
    this.httpReqPaginate.body.sort.by = by;
    this.httpReqPaginate.body.sort.order = (sort.direction == 'asc' ? 0 : 1);
    this.fresh();
  };
  public paginate(event: PageEvent): PageEvent {
    console.log(event);
    this.httpReqPaginate.body.pageNo = event.pageIndex + 1;
    this.httpReqPaginate.body.pageSize = event.pageSize;
    if(!this.httpResPaginate.back && this.httpReqPaginate.body.pageNo == 1) return event;
    this.fresh();
    return event;
  };
}
