import { HTTP_UOW, HttpReqPaginate, HttpResPaginate } from '@_core/_client';
import { NotifyService } from '@_core/_dialog';
import { DialogCommonService } from '@_core/_dialog/dialog-common/srvc.dialog.wrapper';
import { ValidatorService } from '@_core/_form';
import { AppInjector } from '@_core/service';
import { FormBuilder } from '@angular/forms';
import { MatTableDataSource } from '@angular/material/table';

export class LB_Base {
  protected _httpUOW: HTTP_UOW;
  public httpResPaginate: HttpResPaginate = {}

  protected _dialog: DialogCommonService;
  protected _notify: NotifyService;
  protected _fb: FormBuilder;
  protected _vs: ValidatorService;

  public ds = new MatTableDataSource([]); // Data Source

  public cols = []
  constructor(
    public httpReqPaginate: Partial<HttpReqPaginate>,
    public colsExtra: ColsExta[] = [],
  ) {
    this._httpUOW = AppInjector.get(HTTP_UOW);
    this._dialog = AppInjector.get(DialogCommonService);
    this._notify = AppInjector.get(NotifyService);
    this._vs = AppInjector.get(ValidatorService);
    this._fb = AppInjector.get(FormBuilder);

    this.initCols(colsExtra)
    return this;
  }

  initCols(colsExtra: ColsExta[]){
    const finalCol = colsExtra.map(x => x.key)
    this.cols = ['id', 'name', ...finalCol, 'status','desc','updatedAt', 'actions']
  }
}

export interface ColsExta{
  key: string,
  name: string
}
