import { HttpReq } from '@_core/_client';
import { HttpErrorResponse } from '@angular/common/http';
import { Observable, Subject } from 'rxjs';
import { FormSubmit_Inject } from './2.form.inject';
import { ActivatedRoute } from '@angular/router';

export interface SubmitOptions {
  id?: string;
  httpReq: HttpReq;
}
// Template method Pattern
export class FormSubmitHttpService extends FormSubmit_Inject {
  public httpReqGet: HttpReq;
  public httpResSingle: Subject<any> = new Subject<any>()
  public httpReqCreate: HttpReq = {};
  public httpReqUpdate: HttpReq = {};


  constructor(httpReq: HttpReq, public route: ActivatedRoute = null) {
    super();
    this._route = route
    this.httpReqGet = httpReq;
    return this;

  }
  init(){
    this.getById()
    return this
  }

  public getById() {
    if(!this.httpReqGet.resource){
      this.httpReqGet.resource = this._route.snapshot.paramMap.get('id')
    }
    console.log(this.httpReqGet.resource)
    if(this.httpReqGet.resource){
      this._httpUOW.Client.Get(this.httpReqGet).subscribe({
        next: (res: any) => {
          const record = res.Record || res.record
          if(record){
            console.log({ record })
            this.httpResSingle.next(record)
          }
        }
      });
    }
  }
  protected execute(): void {
    const request$ = !!this.httpReqGet.resource ? this.update() : this.create();

    request$.subscribe({
      next: (res) => this.onNext(res),
      error: (err) => this.onError(err),
      complete: () => this.onComplete(),
    });
  }
  public create(): Observable<any> {
    this.httpReqCreate.srvc = this.httpReqCreate.srvc || this.httpReqGet.srvc;
    this.httpReqCreate.cntrl = this.httpReqCreate.cntrl || this.httpReqGet.cntrl;
    this.httpReqCreate.body = this._fs._form.value();
    return this._httpUOW.Client.Add(this.httpReqCreate);
  }

  public update(): Observable<any> {
    this.httpReqUpdate.srvc = this.httpReqUpdate.srvc || this.httpReqGet.srvc;
    this.httpReqUpdate.cntrl = this.httpReqUpdate.cntrl || this.httpReqGet.cntrl;
    this.httpReqUpdate.resource = this.httpReqUpdate.resource || this.httpReqGet.resource;
    this.httpReqUpdate.body = this._fs._form.value;

    return this._httpUOW.Client.Update(this.httpReqUpdate);
  }

  public onNext(res: any): void {
    if(res.status == 'OK'){
      const msg = `Record ${this.httpReqGet.resource ? ' Updated' : ' Created'} Successfully`
      this._dialog.info(this._translate.instant(msg))
        .subscribe({
          next: () => {
            this._fs._form.reset();
            // this._router.navigate([this._template.linkPaginate]);
          }
        })
    } else {
      const msg = `Record not ${this.httpReqGet.resource ? ' Updated' : ' Created'}`
      this._dialog.error(msg)
    }

  }

  public onError(error: HttpErrorResponse): void {
    console.log(error)
    if(error.status > 500){
      this._notify.error({
        title: `Status Code ${error.status}`,
        message: error.message,
        details: error.url
      })
    }
  }

  public onComplete(): void {}

  public onConfirmDenied(): void {}

  public afterSuccess(response: any): void {

  }
}
