import { HttpReq } from '@_core/_client';
import { FormSubmitHttpService, SubmitOptions } from './3.form.submit.http';

// FormSubmitBuilder
export class FSB extends FormSubmitHttpService {

  submit() {
    this.beforeSubmit();

    if (this._fs._form.invalid) {
      return;
    }

    const prompt = this.httpReqGet.resource ? this._dialog.confirmSuccess('Record will be updated') :  this._dialog.confirmSuccess('A new Record will be Created.')

    prompt.subscribe({
      next: (val: boolean) => {
        if(val)
          this.execute();
      }
    })

  }
  public resetForm(){
    this._fs._form.reset()
  }
  protected beforeSubmit(): void {
    this._fs._form.markAllAsTouched();
    this._fs._isSubmitted = true;
    // this._vs._toastr?.clear();
    this._fs.logForm();

  }
}
