import { ChangeDetectorRef, Injectable } from "@angular/core";
import { Subject } from "rxjs";
import { LB } from "../_pagination";
import { BreakpointObserver, Breakpoints } from "@angular/cdk/layout";
import { FSB } from "@_core/_form";


@Injectable({ providedIn: 'root' })
export class TemplateService {
  public title: string = '';
  public layer: string[] = [''];

  public linkPaginate: string = '';
  public linkAdd: string = '';
  public linkUpdate: string = '';

  public ActionFormSave = () => {console.log('ActionFormSave')};
  public ActionFormCancel = () => {console.log('ActionFormCancel')};
  public ActionFormReset = () => {console.log('ActionFormReset')};


  public DATA = new Subject<any>();
  public _cdr: ChangeDetectorRef
  public lb: LB = new LB({})
  public fsb: FSB = new FSB({})
  constructor(public bpo: BreakpointObserver) {
    this.DATA.subscribe({
      next: (data) => {
        console.log({data})
        this.title = data?.title || '';
        this.layer = data?.layer || ['Module', 'Submodule', 'Page'];

        this.linkPaginate = data?.linkPaginate || '';
        this.linkAdd = data?.linkAdd || '';
        this.linkUpdate = data?.linkUpdate || '';
      }
    })
    this.bpoInit();
  }


  public cols: number;
  public SM = false;
  public MD = false;
  public LG = false;
  public bpoInit() {
    this.bpo
      .observe([Breakpoints.XSmall,Breakpoints.Small, Breakpoints.Medium, Breakpoints.Large, Breakpoints.XLarge])
      .subscribe((result) => {
        const bp = result.breakpoints;
        this.SM = this.MD = this.LG = false;
        if (bp[Breakpoints.XSmall] || bp[Breakpoints.Small]) this.SM = true;
        else if (bp[Breakpoints.Medium]) this.MD = true;
        else this.LG = true;
        this._cdr?.detectChanges();
      });
  }
}
export const Btn: IBtn = {
  label: 'Action Label',
  icon: 'icon',
  action: () => {
    console.log(this, 'Triggered');
  }
};
export interface IBtn {
  label: string;
  icon: string;
  action: () => void;
}
