import { FormArray, FormControl, FormGroup } from '@angular/forms';
import { Custom } from '../static';
import { Injectable } from '@angular/core';
import { BaseClassNG } from '@_core/__base';
import { NotifyService, ValidationMessage } from '@_core/_dialog';

@Injectable({
  providedIn: 'root',
})
export class FormService extends BaseClassNG {
  public _form: FormGroup;
  public _isSubmitted = false;
  public _showWarning = false;

  constructor(private _notify: NotifyService) {
    super();
    this._form = this._fb.group({});
  }
  _dd_selected(control: string, value: string, form: FormGroup = this._form) {
    return form.value[control] === value;
  }

  _has(fieldName: string, fg: FormGroup = this._form) {
    return fg?.contains(fieldName);
  }

  _hasVal(fieldName: string, fg: FormGroup = this._form) {
    return Custom.emptyCheck(this._getVal(fieldName, fg));
  }

  _hasGroup(groupName: string, fieldName: string) {
    const group = this._form?.get(groupName) as FormGroup;
    return group?.contains(fieldName);
  }

  _getVal(control: string, group: FormGroup = this._form) {
    return group?.get(control)?.value;
  }

  _checkBoxChecked(val: any, fieldname: string) {
    const selectedArray: FormArray = this._form.get(fieldname) as FormArray;
    if (val.target.checked) {
      selectedArray.push(new FormControl(val.target.value));
    } else {
      let i = 0;
      selectedArray.controls.forEach((ctrl: FormControl) => {
        if (ctrl.value == val.target.value) {
          selectedArray.removeAt(i);
          return;
        }
        i++;
      });
    }
    console.log(selectedArray);
  }

  // FOR LOGGING FORM ERRORS AND WARNINGS
  logForm(group: FormGroup | FormArray = this._form, groupName = '') {
    let logFormMsg: ValidationMessage[] = [];
    const scopeFunc = (group: FormGroup | FormArray = this._form, grp = '') => {
      if (group.invalid) {
        console.group(grp);
        Object.keys(group.controls).forEach((key: string) => {
          const acc = group.get(key); // Abstract Control
          if (acc instanceof FormGroup || acc instanceof FormArray) {
            scopeFunc(acc, grp ? `${grp}.${key}` : key);
          } else if (acc instanceof FormControl) {
            if (acc.status == 'INVALID' || acc.status == 'PENDING') {
              const field = grp == '' ? key : `${grp}.${key}`
              logFormMsg.push({
                field,
                errors: [acc.errors['en']],
              });
              console.error({
                field: key,
                errors: acc.errors,
              });
            } else if (acc.status == 'VALID') {
              console.warn({
                field: key,
                message: 'No Validator Error',
              });
            }
          }
        });
        console.groupEnd();
      }
    };
    scopeFunc(group, groupName);
    if(logFormMsg.length > 0)
      this._notify.validations(logFormMsg)

  }
}
