import {
  Component,
  Input,
  inject,
  signal,
  OnInit,
  ViewEncapsulation,
  ChangeDetectionStrategy,
} from '@angular/core';
import { INotify } from '../model.notify';
import { NotifyService } from '../srvc.notify';


@Component({
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
  standalone: false,
  selector: 'notify-card',
  templateUrl: './notify-card.html',
  styleUrl: './notify-card.scss',
})
export class NotifyCard implements OnInit {
  @Input({ required: true })
  data!: INotify;

  service = inject(NotifyService);

  progress = signal(100);

  pinned = signal(false);

  ngOnInit() {
    if (
      !this.data.autoClose
    )
      return;

    const duration = this.data.duration ?? 5000;

    const interval = 100;

    const decrement = 100 / (duration / interval);

    const timer = setInterval(() => {
      if (this.pinned()) return;

      this.progress.update(
        p => p - decrement
      );

      if (this.progress() <= 0) {
        clearInterval(timer);

        this.close();
      }
    }, interval);
  }

  close() {
    this.service.remove(
      this.data.id
    );
  }

  pin() {
    this.pinned.set(
      !this.pinned()
    );
  }
}
