import { Injectable, signal } from '@angular/core';
import { INotify, INotifyBase, ValidationMessage } from './model.notify';

@Injectable({
  providedIn: 'root',
})
export class NotifyService {
  notifications = signal<INotify[]>([]);

  private id = 0;

  add(notify: INotifyBase) {
    const item: INotify = {
      ...notify,
      id: ++this.id,
      createdAt: new Date(),
      autoClose: true,
      duration: 8000,
    };

    this.notifications.update(x => [...x, item]);
  }

  remove(id: number) {
    this.notifications.update(x =>
      x.filter(n => n.id !== id)
    );
  }

  clear() {
    this.notifications.set([]);
  }
  info(notify : INotifyBase) {
    this.add({
      bg: 'info',
      color: 'dark',
      icon: 'info',
      title: 'Information',
      ...notify
    });
  }
  success(notify : INotifyBase) {
    this.add({
      bg: 'success',
      color: 'light',
      icon: 'check_circle',
      title: 'Success',
      ...notify
    });
  }
  warning(notify : INotifyBase) {
    this.add({
      bg: 'warning',
      color: 'light',
      icon: 'warning',
      title: 'Warning!!',
      ...notify
    });
  }
  validations(validations: ValidationMessage[]) {
    this.add({
      bg: 'warning',
      color: 'light',
      icon: 'rule',
      title: 'Validation Messages',
      validations
    });
  }
  error(notify : INotifyBase) {
    this.add({
      bg: 'danger',
      color: 'light',
      icon: 'error',
      title: 'Server Error',
      ...notify
    });
  }






}
