import { MatDialogConfig } from '@angular/material/dialog';
import { HttpReqDelete, HttpReqPaginate, HttpReqStatus } from '@_core/_client';
import { LB_Base_SortPaginateFilter } from './builder.list.2.sort.paginate.filter';
import { ColsExta } from './builder.list.0.base';

export class LB_Actions extends LB_Base_SortPaginateFilter {
  public httpReqStatus: Partial<HttpReqStatus> = {};
  public httpReqDelete: Partial<HttpReqDelete> = {};
  public httpReqUpdateDelete: Partial<HttpReqStatus> = {};
  constructor(
    public override httpReqPaginate: Partial<HttpReqPaginate>,
    public override colsExtra: ColsExta[] = [],
  ) {
    super(httpReqPaginate, colsExtra);
    // Setting Default if noting Set

    return this;
  }

  public updateStatus(item: { id: any; status: any }) {
    console.log('updateStatus');
    const isNotActive = item.status != 'Active';

    let id = item.id;
    this.httpReqStatus.srvc = this.httpReqStatus.srvc || this.httpReqPaginate.srvc;
    this.httpReqStatus.cntrl = this.httpReqStatus.cntrl || this.httpReqPaginate.cntrl;
    this.httpReqStatus.resource = id;
    this.httpReqStatus.body = {
      id,
      status: isNotActive ? 'Active' : 'DeActive', // 1 Active, 2 DeActive, 0 Delete, -1 None
    };
    const subs = (
      isNotActive
      ? this._dialog.confirmSuccess('Record will be Activated')
      : this._dialog.confirmWarn('Record will be De-Activated')
    );

    subs.subscribe({
      next: (val: boolean) => {
        if (val) {
          this._httpUOW.Client.UpdateStatus(this.httpReqStatus).subscribe({
            next: (res) => {
              if (res.record) {
                item.status = res?.record?.status;
                this._dialog.info(`Record Status ${item?.status} Successfully.`)
              }
            },
          });
        }
      },
      error: () => {
        this._dialog.error('Status not Updated!')
      }
    });
  }
  // Neet to Work
  public updateDelete(item: { id: any; status: any }) {
    console.log('UpadateDelete');
    let id = item.id;
    this.httpReqUpdateDelete.srvc = this.httpReqUpdateDelete.srvc || this.httpReqPaginate.srvc;
    this.httpReqUpdateDelete.cntrl = this.httpReqUpdateDelete.cntrl || this.httpReqPaginate.cntrl;
    this.httpReqUpdateDelete.resource = id;
    this.httpReqUpdateDelete.body = { id, status: 'Delete' };
    this._dialog.confirmWarn('Record will be Soft Deleted').subscribe({
      next: (val: boolean) => {
        if (val) {
          this._httpUOW.Client.UpdateDelete(this.httpReqUpdateDelete).subscribe({
            next: (res) => {
              if (res?.status == 'OK') {
                this._dialog.info('Record Soft Deleted Successfully.')
                this.fresh();
              }
            },
          });
        }
      },
      error: () => {
        this._dialog.error('Record not Deleted!');
      }
    });
  }
  public Delete(item: { id: any; status: any }) {
    console.log('Delete');
    let id = item.id;
    this.httpReqDelete.srvc = this.httpReqDelete.srvc || this.httpReqPaginate.srvc;
    this.httpReqDelete.cntrl = this.httpReqDelete.cntrl || this.httpReqPaginate.cntrl;
    this.httpReqDelete.resource = id;
    this.httpReqDelete.body = { id };
    this._dialog.confirmDanger('Record will be Permenently Deleted.')
    .subscribe({
      next: (val: boolean) => {
        if (val) {
          this._httpUOW.Client.Delete(this.httpReqDelete).subscribe({
            next: (res) => {
              if (res?.status == 'OK') {
                this.fresh();
                this._dialog.warning('Record Permenently Deleted Successfully.')
              }
            },
          });
        }
      },
      error: () => {
        this._dialog.error('Record not Deleted!');
      }
    });
  }

  // Cross Cutting Concerns
  public openImage(data: any, title: any) {
    console.log('openImage');
    const config: MatDialogConfig = {
      panelClass: 'dialog-responsive',
      data: { source: data, title },
    };
    // const dialogRef = this._dialog.open(ImgViewComponent, config);
    // dialogRef.afterClosed().subscribe();
  }

  public printList() {
    console.log('printList');
    this.httpResPaginate.records;
  }
  public exportListToCSV() {
    console.log('exportListToCSV');
    this.httpResPaginate.records;
  }
  public exportListToJSON() {
    console.log('exportListToJSON');
    this.httpResPaginate.records;
  }
  public copyListJSON() {
    console.log('copyListJSON');
    this.httpResPaginate.records;
  }
  public copyItemJSON(item: any) {
    console.log('copyItemJSON');
    item;
  }
  public copyValue(value: any) {
    console.log('copyValue');
    value;
  }
}
