

import { Component, inject, OnDestroy } from "@angular/core";
import { BaseClassNG } from "./base.class.a.ng";
import { EP, HTTP_UOW, HttpReq } from "@_core/_client";
import { CONTROL_HOST_CSS_CLASS, FormService, IMG_URL, ValidatorService } from "@_core/_form";
import { LocalStorageService, StateService } from "@_core/store";
import { UtilService } from "@_core/service";
import { TemplateService } from "@_core/_template";
import { Subscription } from "rxjs";
import { DialogCommonService } from "@_core/_dialog";

// # 1 SOLID PRINCIPLE (Single Responsibility Principle)
// 1. Single responsibility principle: a class should have one, and only one, reason to change;
// 2. When you only want to Inject a Service
@Component({ template: '' })
export abstract class BaseClassProp extends BaseClassNG implements OnDestroy {
  public _httpUwo = inject(HTTP_UOW);
  public _fs = inject(FormService);
  public _vs = inject(ValidatorService);
  public _ss = inject(StateService);
  public _util = inject(UtilService);
  public _template = inject(TemplateService);
  public _dialog = inject(DialogCommonService);
  public _storage = inject(LocalStorageService);
  // Enum Global Property for HTML Template
  public IMG_URL = IMG_URL; // For Template
  public EP = EP; // For Template (Route Permission)
  public httpRequest: HttpReq = {}; // Override this Property for Default Behaviour of HTTP Request
  public DATA: any = {}; // Route Snapshot Data

  public cONTROL_HOST_CSS_CLASS = CONTROL_HOST_CSS_CLASS;
  // Guard Related Properties
  public _id?: string | null = '';
  public _isExist?: boolean | null = false;
  public subscriptionArray: Subscription[] = [];
  constructor() {
    super();
  }
  // Future Reference for using ngOnChanges
  // ngOnChanges(changes: SimpleChanges) {
  //   for (const propName in changes) {
  //     if (changes.hasOwnProperty(propName)) {
  //       switch (propName) {
  //         case 'myFirstInputParameter': {
  //           this.doSomething(change.currentValue)
  //         }
  //       }
  //     }
  //   }
  // }
  ngOnDestroy(): void {
    this.subscriptionArray.forEach((item) => {
      item?.unsubscribe()
    })
  }
}
