import { Injectable } from "@angular/core";
import { DialogService } from "./srvc.dialog";
import { AppInjector } from "@_core/service";
import { MatDialog } from "@angular/material/dialog";

@Injectable({
  providedIn: 'root',
})
export class DialogCommonService {
  public dialog: DialogService;
  public md: MatDialog;
  constructor() {
    this.dialog = AppInjector.get(DialogService)
    this.md = AppInjector.get(MatDialog)
  }
  confirmInfo(
    message: string = 'Do you wanted to make this change',
    title: string = 'Are you sure?',
    color = 'info'){
     return this.dialog.open({
      title,
      message,
      color,
      icon: 'help',
      confirmText: 'Confirm',
      cancelText: 'Cancel',
      showCancel: true,
    }).afterClosed();
  }
  confirmSuccess(
    message: string = 'Do you wanted to make this change.',
    title: string = 'Are you sure?'){
     return this.confirmInfo(message, title, 'success')
  }
  confirmWarn(
    message: string = 'Do you wanted to make this change.',
    title: string = 'Are you sure?'){
     return this.confirmInfo(message, title, 'warning')
  }
  confirmDanger(
    message: string = 'Changes can not be undone.',
    title: string = 'Are you sure?'){
     return this.confirmInfo(message, title, 'danger')
  }
  info(message: string) {
    return this.dialog.open({
      icon: 'info',
      color: 'success',
      title: 'Information',
      message,
    }).afterClosed();
  }
  warning(message: string) {
    return this.dialog.open({
      title: 'Warning',
      icon: 'warning',
      color: 'warning',
      message,
    }).afterClosed();
  }
  error(message: string) {
    return this.dialog.open({
      title: 'Error',
      icon: 'error',
      color: 'danger',
      message,
    }).afterClosed()
  }
  infoSub(message: string) {
    this.info(message).subscribe();
  }
  warningSub(message: string) {
    this.warning(message).subscribe();
  }
  errorSub(message: string) {
    this.error(message).subscribe();
  }

  closeAll(){
    this.md.closeAll();
  }
}
