import { ChangeDetectionStrategy, Component, inject, ViewEncapsulation } from '@angular/core';
import { NotifyService } from './srvc.notify';

@Component({
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
  standalone: false,
  selector: 'notify-container',
  templateUrl: './notify-container.html',
  styles: `
    .notify-container {
      position: fixed;
      top: 16px;
      right: 16px;
      width: 450px;
      max-width: 95vw;
      max-height: 80vh;
      overflow-y: auto;
      z-index: 99999;
      display: flex;
      flex-direction: column;
      gap: 10px;
    }
  `,
})
export class NotifyContainer {
  service = inject(NotifyService);
}
