import { Observable } from 'rxjs';
import { HttpResPaginate, HttpResPaginateOptions, HttpReq, EP, HttpResList, URL_SRVC, HttpReqPaginate, HttpResOptions, HttpReqDelete, HttpReqStatus, HttpResSingle } from './index';
import { HttpBaseService } from './http.1.wrapper';
import { environment } from 'environments/environment';

export class HTTPEnpointsService {
  public readonly client: HttpBaseService;

  constructor(srvc: URL_SRVC, domain: string = environment.API_URL_Gateway) {
    this.client = new HttpBaseService(srvc, domain)
  }
  Add(httpRequest: Partial<HttpReq>): Observable<any> {
    httpRequest.ep = EP.Add;
    return this.client.Post(httpRequest);
  }
  Update(httpRequest: Partial<HttpReq>): Observable<any> {
    httpRequest.ep = EP.Update;
    return this.client.Put(httpRequest);
  }
  UpdateStatus(httpRequest: Partial<HttpReqStatus>): Observable<any> {
    httpRequest.ep = EP.UpdateStatus;
    return this.client.Patch(httpRequest);
  }
  UpdateDelete(httpRequest: Partial<HttpReqStatus>): Observable<any> {
    httpRequest.ep = EP.UpdateDelete;
    return this.client.Patch(httpRequest);
  }
  Delete(httpRequest: Partial<HttpReqDelete>): Observable<any> {
    httpRequest.ep = EP.Delete;
    return this.client.Delete(httpRequest);
  }
  Get(httpRequest: Partial<HttpReq>): Observable<HttpResSingle> {
    httpRequest.ep = EP.Get;
    return this.client.Post(httpRequest);
  }
  Gets(httpRequest: Partial<HttpReq>): Observable<HttpResList> {
    httpRequest.ep = EP.Gets;
    return this.client.Post(httpRequest);
  }
  GetsOption(httpRequest: Partial<HttpReq>): Observable<HttpResOptions> {
    httpRequest.ep = EP.GetsOption;
    return this.client.Post(httpRequest);
  }
  GetsByIds(httpRequest: Partial<HttpReq>): Observable<HttpResList> {
    httpRequest.ep = EP.GetsByIds;
    return this.client.Post(httpRequest);
  }
  GetsLookup(httpRequest: Partial<HttpReq>): Observable<any> {
    httpRequest.ep = EP.GetsLookup;
    return this.client.Get(httpRequest);
  }
  GetsByIdsLookup(httpRequest: Partial<HttpReq>): Observable<any> {
    httpRequest.ep = EP.GetsByIdsLookup;
    return this.client.Post(httpRequest);
  }
  GetsPaginate(httpRequest: Partial<HttpReqPaginate>): Observable<HttpResPaginate> {
    httpRequest.ep = EP.GetsPaginate;
    return this.client.Post(httpRequest);
  }
  GetsPaginateOptions(httpRequest: Partial<HttpReqPaginate>): Observable<HttpResPaginateOptions> {
    httpRequest.ep = EP.GetsPaginateOptions;
    return this.client.Post(httpRequest);
  }
  GetsCSV(httpRequest: Partial<HttpReq>): Observable<any> {
    httpRequest.ep = EP.GetsCSV;
    return this.client.Post(httpRequest);
  }

}
