import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { HttpReq, EP } from './index';
import { AppInjector } from '../service/srvc.app.injector';
import { inject } from '@angular/core';
import { environment } from 'environments/environment';

export class HttpBaseService {
  public readonly http: HttpClient = inject(HttpClient);
  public constructor(public srvc: string, public domain: string = environment.API_URL_Gateway) {
    this.http = AppInjector.get(HttpClient);
  }
  Get(httpRequest: Partial<HttpReq>): Observable<any> {
    return this.http.get(this.setURL(httpRequest), this.setOptions(httpRequest));
  }
  Post(httpRequest: Partial<HttpReq>): Observable<any> {
    return this.http.post(this.setURL(httpRequest), httpRequest?.body || { includes: null }, this.setOptions(httpRequest));
  }
  Put(httpRequest: Partial<HttpReq>): Observable<any> {
    return this.http.put(this.setURL(httpRequest), httpRequest.body, this.setOptions(httpRequest));
  }
  Patch(httpRequest: Partial<HttpReq>): Observable<any> {
    return this.http.patch(this.setURL(httpRequest), httpRequest.body, this.setOptions(httpRequest));
  }
  Delete(httpRequest: Partial<HttpReq>): Observable<any> {
    return this.http.delete(this.setURL(httpRequest), this.setOptions(httpRequest));
  }
  private setURL(httpRequest: Partial<HttpReq>): string {
    if(httpRequest.fullUrl) return httpRequest.fullUrl;

    let result = `${httpRequest.domain || this.domain}/${httpRequest.srvc || this.srvc}/v1/${httpRequest.cntrl}`;
    if(httpRequest?.ep) result += '/' + httpRequest.ep;
    if(httpRequest?.resource) result += '/' + httpRequest.resource;
    return result;
  }
  private setOptions(httpRequest: Partial<HttpReq>) {
    return {
      params : httpRequest.query
    }
  }
  private get defaultParam(): HttpReq {
    return {
      domain: this.domain,
      srvc: this.srvc,
      cntrl: '',
      ep: EP.NotSet,
      query: undefined,
    };
  }
}
