import { inject, Injectable, Injector } from '@angular/core';
import { BehaviorSubject, Subject } from 'rxjs';
import { ROUTEZ } from '../_route/menu-items';
import { Permission, SideBarMenus } from '../_route';
import { EP } from '../_client';
import { DirectionService } from '../_template';

@Injectable({
  providedIn: 'root',
})
export class StateService {
  // TRANSACTION
  public activeSideBarParent: SideBarMenus;
  public activeSideBarParentId: number;
  public activeSideBarLink:string;
  public sideBarMenus: SideBarMenus[];
  public sideBarMenusFlat: SideBarMenus[] = [];
  public permission: Permission[];
  transBatch = true;
  public DATA = new Subject<any>()
  public isLoading = new BehaviorSubject(false);

  constructor(public injector: Injector) {
    const dirService = inject(DirectionService)
    dirService.setLanguage('en');
    this.sideBarMenus = ROUTEZ
    ROUTEZ.forEach(x => {
      this.flatSideBarMenu(x);
    })
  }
  flatSideBarMenu(menu: SideBarMenus){
    this.sideBarMenusFlat.push(menu)
    if(menu.submenu.length) {
      menu.submenu.forEach(y => {
        this.flatSideBarMenu(y)
      })
    }
  }
  public checkPermission(action: EP) {
    return this.permission?.find((a) => a.name == action);
  }
  public EDUCTION: any[] = [
    { id: 'Middle', name: 'Middle' },
    { id: 'Matric', name: 'Matric' },
    { id: 'Inter', name: 'Inter' },
    { id: 'Graduation', name: 'Graduation' },
    { id: 'Masters', name: 'Masters' },
  ];
  public GENDER: any[] = [
    { id: 'Male', name: 'Male' },
    { id: 'Female', name: 'Female' },
  ];
  public STATUS : any[] = [
    { id: "None", name: "None" },
    { id: "Active", name: "Active" },
    { id: "DeActive", name: "DeActive" },
    { id: "Archived", name: "Archived" },
    { id: "Delete", name: "Delete" },
    // { id: "Published", name: "Published" },
    // { id: "Pending", name: "Pending" },
    // { id: "NonVerified", name: "NonVerified" },
    // { id: "Verified", name: "Verified" }
  ];
}
