import { AppInjector } from '@_core/service/srvc.app.injector.js';
import { FormService } from './1.srvc.form';
import { ValidatorService } from '../validator';
import { HTTP_UOW } from '@_core/_client';
import { TranslateService } from '@ngx-translate/core';
import { ActivatedRoute, Router } from '@angular/router';
import { DialogCommonService, NotifyService } from '@_core/_dialog';
import { TemplateService } from '@_core/_template';

export class FormSubmit_Inject  {
  public _fs: FormService;
  public _httpUOW: HTTP_UOW;
  public _vs: ValidatorService;
  public _dialog: DialogCommonService;
  public _notify: NotifyService
  public _router: Router
  public _route: ActivatedRoute
  // public _template: TemplateService

  public _translate: TranslateService

  constructor() {
    this._fs = AppInjector.get(FormService)
    this._httpUOW = AppInjector.get(HTTP_UOW)
    // this._template = AppInjector.get(TemplateService)
    this._vs = AppInjector.get(ValidatorService)
    this._dialog = AppInjector.get(DialogCommonService)
    this._notify = AppInjector.get(NotifyService)
    this._translate = AppInjector.get(TranslateService)
    this._router = AppInjector.get(Router)
    // this._route = AppInjector.get(ActivatedRoute)
  }
}
